-- Name: addresses; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.addresses (
    id bigint NOT NULL,
    consignee_id bigint NOT NULL,
    country_id bigint,
    governorate_id bigint,
    state_id bigint,
    place_id bigint,
    city_id bigint,
    zipcode character varying(191),
    "streetAddress" text,
    longitude numeric(10,7),
    latitude numeric(10,7),
    location_url text,
    label character varying(191),
    approved boolean DEFAULT false NOT NULL,
    approved_at timestamp(0) without time zone,
    approved_by bigint,
    times_used integer DEFAULT 0 NOT NULL,
    last_used_at timestamp(0) without time zone,
    first_approved_shipment_id bigint,
    is_active boolean DEFAULT true NOT NULL,
    address_signature character varying(191),
    deleted_at timestamp(0) without time zone,
    created_at timestamp(0) without time zone,
    updated_at timestamp(0) without time zone,
    is_verified boolean DEFAULT false NOT NULL,
    verification_method character varying(191),
    proof_url text,
    proof_note text,
    verified_at timestamp(0) without time zone,
