    location_url character varying(191),
    longitude numeric(10,7),
    latitude numeric(10,7),
    is_walkin boolean DEFAULT false NOT NULL,
    fee_payer character varying(191),
    is_outsourced boolean DEFAULT false NOT NULL,
    created_at timestamp(0) without time zone,
    updated_at timestamp(0) without time zone,
    deleted_at timestamp(0) without time zone,
    pickup_address_id bigint,
    delivery_address_id bigint,
    delivery_fee_before_discount numeric(12,3),
    delivery_fee_discount numeric(12,3),
    partner_shipment_id character varying(191),
    marketplace_partner_id bigint,
    pickup_request_id bigint,
    final_hub_type character varying(191),
    final_hub_id bigint,
    current_hub_type character varying(191),
    current_hub_id bigint,
    from_hub_type character varying(191),
    from_hub_id bigint,
    created_source character varying(255),
    merchant_invoice_id bigint,
    delivered_at timestamp(0) without time zone,
    picked_at timestamp(0) without time zone,
    partner_shipment_tracking_number character varying(191),
    exception_type character varying(191),
    return_kind character varying(191),
    return_to_type character varying(191),
    return_to_id bigint,
    return_fee_before_discount numeric(10,3),
    return_fee_discount numeric(10,3),
    return_fee numeric(10,3),
    return_fee_source character varying(191),
    return_request_id bigint,
    container_id bigint,
    current_container_id bigint,
    delete_reason text,
    is_facility_to_facility boolean DEFAULT false NOT NULL,
    delivery_partner_id bigint,
    routing_type character varying(255) DEFAULT 'internal'::character varying NOT NULL,
    is_sandbox boolean DEFAULT false NOT NULL,
    is_home_to_facility boolean DEFAULT false NOT NULL,
    consignee_name character varying(191),
    consignee_phone character varying(191),
    requires_customs boolean DEFAULT false NOT NULL,
    customs_submitted_at timestamp(0) without time zone,
    customs_cleared_at timestamp(0) without time zone,
    weight numeric(10,3),
    length numeric(8,2),
    width numeric(8,2),
    height numeric(8,2),
    package_count integer DEFAULT 1,
    currency character varying(3) DEFAULT 'OMR'::character varying,
    ioss_number character varying(50),
    manifest_date timestamp(0) without time zone,
    clearance_waybill_no character varying(100),
    order_date timestamp(0) without time zone,
    chargeable_weight numeric(10,3),
    pcs_items integer,
    box_no character varying(100),
    invoice_link text,
    waybill_link text,
    linehaul_waybill_no character varying(100),
    product_code character varying(191),
    product_code_id bigint,
    pending_action character varying(191),
    operational_visibility character varying(32) DEFAULT 'released'::character varying NOT NULL,
    partner_inbound_batch_id bigint,
    is_operational boolean DEFAULT true NOT NULL,
    partner_hawb_id bigint,
    shipper_partner_id bigint,
    weight_unit character varying(10),
    dimension_unit character varying(10),
    location_plus_code character varying(191),
    declared_value numeric(12,3),
    declared_value_currency character varying(3) DEFAULT 'USD'::character varying,
    sender_phone character varying(191),
    sender_name character varying(191),
    customs_amount numeric(12,3) DEFAULT '0'::numeric,
    consignee_national_id character varying(191),
    geo_source character varying(32),
    zone_resolution_method character varying(48),
    contacted_at timestamp(0) without time zone,
    partner_delivery_release_at timestamp(0) without time zone,
    partner_pre_delivery_status character varying(64),
    returned_at timestamp(0) without time zone,
    return_payment_declared character varying(10),
    CONSTRAINT shipments_created_source_check CHECK (((created_source)::text = ANY (ARRAY[('dashboard'::character varying)::text, ('driver'::character varying)::text, ('unCreated'::character varying)::text, ('partner_inbound'::character varying)::text]))),
    CONSTRAINT shipments_routing_type_check CHECK (((routing_type)::text = ANY (ARRAY[('internal'::character varying)::text, ('partner'::character varying)::text])))
);


