    id bigint NOT NULL,
    description text NOT NULL,
    declared_value numeric(10,2) NOT NULL,
    hs_code character varying(191) NOT NULL,
    origin_country character varying(191) NOT NULL,
    export_reason character varying(191) NOT NULL,
    invoice_path character varying(191),
    status character varying(255) DEFAULT 'draft'::character varying NOT NULL,
    created_at timestamp(0) without time zone,
    updated_at timestamp(0) without time zone,
    shipment_id bigint,
    declaration_number character varying(50),
    customs_authority_ref character varying(100),
    submission_method character varying(20) DEFAULT 'manual'::character varying NOT NULL,
    rejection_reason text,
    review_notes text,
    required_documents json,
    submission_attempts smallint DEFAULT '0'::smallint NOT NULL,
    duty_amount numeric(12,2),
    tax_amount numeric(12,2),
    duty_payment_status character varying(20),
    submitted_at timestamp(0) without time zone,
    cleared_at timestamp(0) without time zone,
    rejected_at timestamp(0) without time zone,
    declared_value_currency character varying(3) DEFAULT 'OMR'::character varying,
    duty_currency character varying(3) DEFAULT 'OMR'::character varying,
    tax_currency character varying(3) DEFAULT 'OMR'::character varying,
    sales_tax_amount numeric(12,3) DEFAULT '0'::numeric,
    sales_tax_currency character varying(3) DEFAULT 'OMR'::character varying,
    declaration_type character varying(20) DEFAULT 'import'::character varying,
    package_count integer DEFAULT 1,
    gross_weight numeric(10,3),
    weight_unit character varying(5) DEFAULT 'KG'::character varying,
    declaration_provisional_no character varying(50),
    regime character varying(255),
    bayan_declaration_type character varying(20),
    entry_port_type character varying(255),
    port_of_entry_code character varying(20),
