    inspection_at_premises boolean DEFAULT false NOT NULL,
    version_no integer DEFAULT 1 NOT NULL,
    statistical_declaration boolean DEFAULT false NOT NULL,
    bayan_status character varying(20) DEFAULT 'draft'::character varying NOT NULL,
    bayan_response_code character varying(5),
    bayan_response_message text,
    bayan_error_codes json,
    last_bayan_sync_at timestamp(0) without time zone,
    bayan_mhb_subject character varying(255),
    provider character varying(30) DEFAULT 'bayan'::character varying NOT NULL,
    country_code character varying(3) DEFAULT 'OM'::character varying NOT NULL,
    CONSTRAINT customs_declarations_entry_port_type_check CHECK (((entry_port_type)::text = ANY (ARRAY[('S'::character varying)::text, ('A'::character varying)::text, ('L'::character varying)::text]))),
    CONSTRAINT customs_declarations_regime_check CHECK (((regime)::text = ANY (ARRAY[('IMP'::character varying)::text, ('EXP'::character varying)::text]))),
    CONSTRAINT customs_declarations_status_check CHECK (((status)::text = ANY (ARRAY[('draft'::character varying)::text, ('submitted'::character varying)::text, ('approved'::character varying)::text])))
);


