-- Name: financial_requests; Type: TABLE; Schema: sandbox; Owner: postgres
--

CREATE TABLE sandbox.financial_requests (
    id bigint NOT NULL,
    owner_id bigint NOT NULL,
    owner_type character varying(191) NOT NULL,
    code character varying(191) NOT NULL,
    type character varying(255) NOT NULL,
    payee_id character varying(191),
    period character varying(191),
    amount numeric(12,3) DEFAULT '0'::numeric NOT NULL,
    notes text,
    status character varying(255) DEFAULT 'pending'::character varying NOT NULL,
    approved_at timestamp(0) without time zone,
    approved_by bigint,
    attachment_path character varying(191),
    created_by bigint NOT NULL,
    reviewed_at timestamp(0) without time zone,
    reviewed_by bigint,
    period_date date,
    payee_name character varying(191),
    created_at timestamp(0) without time zone,
    updated_at timestamp(0) without time zone,
    financial_proof character varying(191),
    confirmed_by bigint,
    confirmed_at timestamp(0) without time zone,
    partner_id bigint,
    breakdown json,
    approved_amount numeric(12,3) DEFAULT '0'::numeric NOT NULL,
    confirmed_amount numeric(12,3) DEFAULT '0'::numeric NOT NULL,
    closed_by bigint,
    closed_at timestamp(0) without time zone,
    CONSTRAINT financial_requests_status_check CHECK (((status)::text = ANY (ARRAY[('pending'::character varying)::text, ('partially_approved'::character varying)::text, ('approved'::character varying)::text, ('rejected'::character varying)::text, ('confirmed'::character varying)::text, ('closed'::character varying)::text]))),
    CONSTRAINT financial_requests_type_check CHECK (((type)::text = ANY (ARRAY[('merchant_settlement'::character varying)::text, ('driver_salary'::character varying)::text, ('branch_settlement'::character varying)::text, ('other'::character varying)::text, ('workspace_funding_driver'::character varying)::text, ('workspace_funding_merchant'::character varying)::text, ('workspace_sweep_request'::character varying)::text, ('company_partner_payout'::character varying)::text, ('workspace_local_settlement_request'::character varying)::text])))
);


ALTER TABLE sandbox.financial_requests OWNER TO postgres;

